import java.util.HashSet;
import java.util.Set;

public class Example {
    public void processHistory() {
        Set<String> previousExtensions = new HashSet<>(10);
        previousExtensions.add("java");
        previousExtensions.add("xml");
        System.out.println(previousExtensions);
    }
}

